+	f := out.TemplateFuncs()
+
+	tpl, err := template.New("t").Funcs(f).Parse(`{{ Truncate 3 "." . }}`)
+	if err != nil {
+		t.Fatalf("parse: %v", err)
+	}
+
+	in := termenv.CSI + "1m" + "abcdef"
+	var buf bytes.Buffer
+	if err := tpl.Execute(&buf, in); err != nil {
