+	resetSeq := termenv.CSI + termenv.ResetSeq + "m"
+	startSeq := strings.TrimSuffix(termenv.String("").Bold().String(), resetSeq)
+	want := startSeq + "ab." + resetSeq
+	if buf.String() != want {
+		t.Fatalf("unexpected output:\nwant: %q\n got: %q", want, buf.String())
